const workflowNameTaken = `-- name: WorkflowNameTaken :one
SELECT EXISTS (
    SELECT 1 FROM workflows
    WHERE workspace_id = $1 AND lower(name) = lower($2) AND deleted_at IS NULL AND id <> $3
) AS taken
`

type WorkflowNameTakenParams struct {
	WorkspaceID ids.UUID `json:"workspace_id"`
	Name        string   `json:"name"`
	ID          ids.UUID `json:"id"`
}

// WorkflowNameTaken reports whether another live workflow has the name.
func (q *Queries) WorkflowNameTaken(ctx context.Context, arg WorkflowNameTakenParams) (bool, error) {
	row := q.db.QueryRow(ctx, workflowNameTaken, arg.WorkspaceID, arg.Name, arg.ID)
	var taken bool
	err := row.Scan(&taken)
	return taken, err
}

const workflowsCallingWorkflow = `-- name: WorkflowsCallingWorkflow :many
SELECT w.id, w.name FROM workflows w
JOIN workflow_versions v ON v.id = w.live_version_id
WHERE w.workspace_id = $1 AND w.status = 'live' AND w.deleted_at IS NULL AND w.id <> $2
  AND v.compiled -> 'references' -> 'workflows' ? $3::text
`

type WorkflowsCallingWorkflowParams struct {
	WorkspaceID ids.UUID `json:"workspace_id"`
	WorkflowID  ids.UUID `json:"workflow_id"`
	PublicID    string   `json:"public_id"`
}

type WorkflowsCallingWorkflowRow struct {
	ID   ids.UUID `json:"id"`
	Name string   `json:"name"`
}

// WorkflowsCallingWorkflow returns the live workflows whose live version
// calls the workflow, which may therefore not be archived.
func (q *Queries) WorkflowsCallingWorkflow(ctx context.Context, arg WorkflowsCallingWorkflowParams) ([]WorkflowsCallingWorkflowRow, error) {
	rows, err := q.db.Query(ctx, workflowsCallingWorkflow, arg.WorkspaceID, arg.WorkflowID, arg.PublicID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorkflowsCallingWorkflowRow
	for rows.Next() {
		var i WorkflowsCallingWorkflowRow
		if err := rows.Scan(&i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
